export default function TelaAniversariantes() {
  const [aniversariantes, setAniversariantes] = useState<Aniversariante[]>([]);
  const [novoNome, setNovoNome] = useState('');
  const [novaData, setNovaData] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [mensagem, setMensagem] = useState('');
  const [aniversarianteSelecionado, setAniversarianteSelecionado] = useState<Aniversariante | null>(null);
  const [felicitacaoHoje, setFelicitacaoHoje] = useState<Aniversariante[]>([]);
  const [todosAniversariantes, setTodosAniversariantes] = useState<Aniversariante[]>([]);
  const [mostrarForm, setMostrarForm] = useState(false);
  const [modalMensagensVisible, setModalMensagensVisible] = useState(false);
  const [fotosUsuarios, setFotosUsuarios] = useState<{ [nome: string]: string }>(FOTOS_PADRAO);
  const [uidAtual, setUidAtual] = useState<string | null>(auth.currentUser?.uid ?? null);
  const [fotoVisualizada, setFotoVisualizada] = useState<{ nome: string; uri: string } | null>(null);
  const [funçõesSelecionadas, setFuncoesSelecionadas] = useState<string[]>([]);
  const [novaFuncao, setNovaFuncao] = useState('');
  const [modalFuncoesVisible, setModalFuncoesVisible] = useState(false);
  const [nomeEditado, setNomeEditado] = useState('');
  const [dataEditada, setDataEditada] = useState('');

  const navigation = useNavigation();
  const nomeUsuarioAtual = uidAtual ? UID_TO_NOME[uidAtual] : undefined;

  useEffect(() => {
    buscarAniversariantes();
    buscarFotosUsuarios();
  }, []);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, user => {
      setUidAtual(user?.uid ?? null);
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const unsubscribe = onSnapshot(collection(db, 'presencas'), snapshot => {
      const fotosBanco = snapshot.docs.reduce((acc, docSnap) => ({
        ...acc,
        ...(docSnap.data().fotosUsuarios || {}),
      }), {});
      const fotosBancoPorUid = snapshot.docs.reduce((acc, docSnap) => ({
        ...acc,
        ...fotosPorUidParaNomes(docSnap.data().fotosPorUid || {}),
      }), {});

      setFotosUsuarios(prev => {
        const fotosAtualizadas = { ...FOTOS_PADRAO, ...prev, ...fotosBanco, ...fotosBancoPorUid };
        AsyncStorage.setItem('fotosUsuarios', JSON.stringify(fotosAtualizadas)).catch(() => {});
        return fotosAtualizadas;
      });
    });

    return () => unsubscribe();
  }, []);

  async function buscarFotosUsuarios() {
    try {
      const presencaSnap = await getDocs(collection(db, 'presencas'));
      let fotosBanco: { [nome: string]: string } = {};
      let fotosBancoPorUid: { [nome: string]: string } = {};

      fotosBanco = presencaSnap.docs.reduce((acc, docSnap) => ({
        ...acc,
        ...(docSnap.data().fotosUsuarios || {}),
      }), {});
      fotosBancoPorUid = presencaSnap.docs.reduce((acc, docSnap) => ({
        ...acc,
        ...fotosPorUidParaNomes(docSnap.data().fotosPorUid || {}),
      }), {});

      const fotosLocalStr = await AsyncStorage.getItem('fotosUsuarios');
      let fotosLocal: { [nome: string]: string } = {};
      if (fotosLocalStr) {
        try {
          fotosLocal = JSON.parse(fotosLocalStr);
        } catch {}
      }

      setFotosUsuarios({ ...FOTOS_PADRAO, ...fotosBanco, ...fotosLocal, ...fotosBancoPorUid });
    } catch {}
  }

  function normalizarNome(nome: string) {
    return nome
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/\b(pr|pra|pastor|pastora)\.?\b/gi, '')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  }

  function obterFotoAniversariante(nome: string) {
    const chaveFoto = obterChaveFoto(nome);
    if (chaveFoto) return fotosUsuarios[chaveFoto];

    return `https://ui-avatars.com/api/?name=${encodeURIComponent(nome)}`;
  }

  function obterChaveFoto(nome: string) {
    if (fotosUsuarios[nome]) return nome;

    const nomeNormalizado = normalizarNome(nome);
    return Object.keys(fotosUsuarios).find(chave => {
      const chaveNormalizada = normalizarNome(chave);
      return (
        chaveNormalizada === nomeNormalizado ||
        nomeNormalizado.includes(chaveNormalizada) ||
        chaveNormalizada.includes(nomeNormalizado)
      );
    });
  }

  function podeEditarFoto(nome: string) {
    return !!nomeUsuarioAtual && normalizarNome(nomeUsuarioAtual) === normalizarNome(nome);
  }

  function alternarFuncao(função: string) {
    setFuncoesSelecionadas(funçõesAtuais =>
      funçõesAtuais.includes(função)
        ? funçõesAtuais.filter(item => item !== função)
        : [...funçõesAtuais, função]
    );
  }

  function editarFuncaoSelecionada(index: number, valor: string) {
    setFuncoesSelecionadas(funçõesAtuais =>
      funçõesAtuais.map((função, itemIndex) => itemIndex === index ? valor : função)
    );
  }

  function excluirFuncaoSelecionada(index: number) {
    setFuncoesSelecionadas(funçõesAtuais => funçõesAtuais.filter((_, itemIndex) => itemIndex !== index));
  }

  function abrirEdicaoFuncoes(aniversariante: Aniversariante) {
    setAniversarianteSelecionado(aniversariante);
    setNomeEditado(aniversariante.nome);
    setDataEditada(aniversariante.data.replace(/-/g, '/'));
    setFuncoesSelecionadas(aniversariante.funções || []);
    setNovaFuncao('');
    setModalFuncoesVisible(true);
  }

  async function salvarFuncoesAniversariante() {
    if (!aniversarianteSelecionado?.id) return;

    const dataFormatada = dataEditada.replace(/\//g, '-');
    if (!nomeEditado.trim() || !dataFormatada.match(/^\d{2}-\d{2}-\d{4}$/)) {
      Alert.alert('Preencha corretamente o nome e a data (dd-mm-aaaa)');
      return;
    }

    const funções = [...funçõesSelecionadas, novaFuncao]
      .map(função => função.trim())
      .filter(Boolean)
      .filter((função, index, lista) => lista.findIndex(item => item.toLowerCase() === função.toLowerCase()) === index);

    try {
      await updateDoc(doc(db, 'aniversariantes', aniversarianteSelecionado.id), {
        nome: nomeEditado.trim(),
        data: dataFormatada,
        funções,
      });

      const chaveFotoAtual = obterChaveFoto(aniversarianteSelecionado.nome);
      if (chaveFotoAtual && aniversarianteSelecionado.nome !== nomeEditado.trim()) {
        const novasFotos = { ...fotosUsuarios, [nomeEditado.trim()]: fotosUsuarios[chaveFotoAtual] };
        setFotosUsuarios(novasFotos);
        await salvarFotosUsuarios(novasFotos);
      }

      setModalFuncoesVisible(false);
      setNomeEditado('');
      setDataEditada('');
      setNovaFuncao('');
      setFuncoesSelecionadas([]);
      buscarAniversariantes();
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar as funções.');
    }
  }

  async function salvarFotosUsuarios(novasFotos: { [nome: string]: string }) {
    try {
      await AsyncStorage.setItem('fotosUsuarios', JSON.stringify(novasFotos));
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar a foto.');
    }
  }

  async function alterarFotoAniversariante(nome: string) {
    if (!uidAtual || !podeEditarFoto(nome)) {
      setFotoVisualizada({ nome, uri: obterFotoAniversariante(nome) });
      return;
    }

    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      aspect: [1, 1],
      quality: 0.7,
      base64: false,
    });

    if (result.canceled || !result.assets?.length) return;

    const asset = result.assets[0];
    const cropQuadrado = montarCropQuadrado(asset.width, asset.height);
    const manipResult = await ImageManipulator.manipulateAsync(
      asset.uri,
      [
        ...(cropQuadrado ? [{ crop: cropQuadrado }] : []),
        { resize: { width: 320 } },
      ],
      {
        compress: 0.45,
        format: ImageManipulator.SaveFormat.JPEG,
        base64: true,
      }
    );

    const chaveFoto = obterChaveFoto(nome) || nome;
    const base64Image = `data:image/jpeg;base64,${manipResult.base64}`;
    const novasFotos = { ...fotosUsuarios, [chaveFoto]: base64Image };
    setFotosUsuarios(novasFotos);
    await AsyncStorage.setItem('fotosUsuarios', JSON.stringify(novasFotos));
    await salvarFotoUsuarioNoBanco(uidAtual, base64Image);
  }

  async function buscarAniversariantes() {
    try {
      const snap = await getDocs(collection(db, 'aniversariantes'));
      const lista: Aniversariante[] = [];
      snap.forEach(docSnap => {
        const data = docSnap.data();
        lista.push({ id: docSnap.id, ...data, mensagens: data.mensagens || [] } as Aniversariante);
      });

      // Função para calcular a próxima data de aniversário
      const calcularProximaData = (dataAniversario: string) => {
        const parts = dataAniversario.split(/[-\/]/).map(Number);
        const dia = parts[0] || 1;
        const mes = parts[1] || 1;
        const hoje = new Date();
        const anoAtual = hoje.getFullYear();
        let proximaData = new Date(anoAtual, mes - 1, dia);
        if (proximaData < hoje) {
          proximaData = new Date(anoAtual + 1, mes - 1, dia);
        }
        return proximaData;
      };

      // Ordenar por proximidade da data de aniversário
      const todos = [...lista].sort((a, b) => {
        const dataA = calcularProximaData(a.data);
        const dataB = calcularProximaData(b.data);
        return dataA.getTime() - dataB.getTime();
      });
      setTodosAniversariantes(todos);

      const mesAtual = new Date().getMonth() + 1;
      const filtrados = lista.filter(a => {
        const parts = a.data.split(/[-\/]/);
        const mes = parts[1];
        return Number(mes) === mesAtual;
      });
      setAniversariantes(filtrados);

      const hoje = new Date();
      const diaHoje = String(hoje.getDate()).padStart(2, '0');
      const mesHoje = String(hoje.getMonth() + 1).padStart(2, '0');
      const aniversariantesHoje = lista.filter(a => {
        const [dia, mes] = a.data.split(/[-\/]/);
        return dia === diaHoje && mes === mesHoje;
      });
      setFelicitacaoHoje(aniversariantesHoje);

    } catch (e) {
      Alert.alert('Erro', 'Não foi possível carregar os aniversariantes.');
    }
  }

  async function adicionarAniversariante() {
    const dataFormatada = novaData.replace(/\//g, '-');
    if (!novoNome || !dataFormatada.match(/^\d{2}-\d{2}-\d{4}$/)) {
      Alert.alert('Preencha corretamente o nome e a data (dd-mm-aaaa)');
      return;
    }
    try {
      await addDoc(collection(db, 'aniversariantes'), {
        nome: novoNome,
        data: dataFormatada,
        funções: [...funçõesSelecionadas, novaFuncao]
          .map(função => função.trim())
          .filter(Boolean)
          .filter((função, index, lista) => lista.findIndex(item => item.toLowerCase() === função.toLowerCase()) === index),
        criadoEm: Timestamp.now(),
        mensagens: [],
      });
      setNovoNome('');
      setNovaData('');
      setNovaFuncao('');
      setFuncoesSelecionadas([]);
      setMostrarForm(false);
      buscarAniversariantes();
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível adicionar.');
    }
  }

  async function enviarMensagem() {
    if (!mensagem || !aniversarianteSelecionado) return;
    try {
      const ref = doc(db, 'aniversariantes', aniversarianteSelecionado.id!);
      await updateDoc(ref, {
        mensagens: arrayUnion({
          texto: mensagem.trim(),
          enviadoEm: Timestamp.now(),
        }),
      });
      setMensagem('');
      setModalVisible(false);
      buscarAniversariantes();
      Alert.alert('Mensagem enviada!', `Sua mensagem para ${aniversarianteSelecionado.nome} foi enviada.`);
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível enviar a mensagem.');
    }
  }

  async function responderMensagem(index: number, emoji: string) {
    if (!aniversarianteSelecionado) return;
    try {
      const ref = doc(db, 'aniversariantes', aniversarianteSelecionado.id!);
      const novasMensagens = (aniversarianteSelecionado.mensagens || []).map((msg, i) => {
        if (i === index) {
          if (typeof msg === 'string') {
            return { texto: msg, reacao: emoji };
          }
          return { ...msg, reacao: emoji };
        }
        return msg;
      });
      await updateDoc(ref, { mensagens: novasMensagens });
      buscarAniversariantes();
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível enviar a reação.');
    }
  }

  return (
    <LinearGradient
      colors={['#0B1630', '#161934', '#241A3D']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.bg}
    >
      <ScrollView contentContainerStyle={styles.scroll}>
        <View style={styles.container}>
          {/* HEADER */}
          <Neumorphic style={styles.headerNeumorphic}>
            <View style={styles.headerRow}>
              <TouchableOpacity
                style={styles.headerIconBtn}
                onPress={() => navigation.navigate('Inicio' as never)}
                activeOpacity={0.7}
              >
                <MaterialIcons name="home" size={28} color="#ff9800" />
              </TouchableOpacity>
              <Text style={styles.headerTitle}>Aniversariantes</Text>
              <TouchableOpacity
                style={styles.headerIconBtn}
                onPress={() => navigation.goBack()}
                activeOpacity={0.7}
              >
                <MaterialIcons name="arrow-back-ios" size={24} color="#a084e8" />
              </TouchableOpacity>
            </View>
          </Neumorphic>
          {/* FIM HEADER */}

          {/* Aniversariantes de hoje */}
          {felicitacaoHoje.length > 0 && (
            <>
              <Text style={styles.tituloHoje}>🎉 Aniversariantes de Hoje!</Text>
              <FlatList
                data={felicitacaoHoje}
                keyExtractor={item => item.id || item.nome + item.data}
                contentContainerStyle={{ paddingBottom: 10, alignItems: 'center' }}
                renderItem={({ item }) => (
                  <Neumorphic style={[styles.cardHoje, { maxWidth: 340, width: '98%' }]}>
                    <View style={styles.cardDestaqueContent}>
                      <View style={styles.cakeEmojiBox}>
                        <TouchableOpacity onPress={() => alterarFotoAniversariante(item.nome)} activeOpacity={0.8}>
                          <Image
                            source={{ uri: obterFotoAniversariante(item.nome) }}
                            style={styles.avatarDestaque}
                          />
                          <View style={styles.editarAvatarBadge}>
                            <MaterialIcons name={podeEditarFoto(item.nome) ? 'photo-camera' : 'visibility'} size={13} color="#fff" />
                          </View>
                        </TouchableOpacity>
                      </View>
                      <View style={styles.cardDestaqueTextos}>
                        <Text
                          style={styles.nomeDestaque}
                          numberOfLines={2}
                          ellipsizeMode="tail"
                        >
                          {item.nome}
                        </Text>
                        <Text style={styles.dataDestaque}>{exibirDiaMes(item.data)}</Text>
                        <View style={styles.botoesContainer}>
                          <TouchableOpacity
                            style={styles.botaoParabensDestaque}
                            onPress={() => {
                              setAniversarianteSelecionado(item);
                              setModalVisible(true);
                            }}
                            activeOpacity={0.85}
                          >
                            <MaterialCommunityIcons name="message-text" size={22} color="#fff" />
                            <Text style={styles.textoParabensDestaque}>Envie Parabéns!</Text>
                            <Text style={{ fontSize: 28, marginLeft: 6 }}>👏</Text>
                          </TouchableOpacity>
                          {item.mensagens && item.mensagens.length > 0 && (
                            <TouchableOpacity
                              style={styles.botaoVerMensagens}
                              onPress={() => {
                                setAniversarianteSelecionado(item);
                                setModalMensagensVisible(true);
                              }}
                              activeOpacity={0.85}
                            >
                              <MaterialIcons name="message" size={20} color="#fff" />
                              <Text style={styles.textoVerMensagens}>
                                Ver Mensagens ({item.mensagens.length})
                              </Text>
                            </TouchableOpacity>
                          )}
                        </View>
                      </View>
                    </View>
                  </Neumorphic>
                )}
              />
            </>
          )}

          <Text style={styles.subtitulo}>🎉 Todos os aniversariantes</Text>

          {/* Formulario de adicionar aniversariante */}
          {!mostrarForm && (
            <Neumorphic style={styles.novoBtnNeumorphic}>
              <TouchableOpacity
                style={styles.novoBtn}
                onPress={() => setMostrarForm(true)}
                activeOpacity={0.85}
              >
                <MaterialIcons name="add" size={24} color="#a084e8" style={{ marginRight: 10 }} />
                <Text style={styles.novoBtnText}>Add sua data de aniversário</Text>
              </TouchableOpacity>
            </Neumorphic>
          )}

          {mostrarForm && (
            <Neumorphic style={styles.formMelhorada}>
              <View style={styles.inputBox}>
                <MaterialIcons name="person" size={22} color="#2196F3" style={{ marginRight: 6 }} />
                <TextInput
                  style={styles.inputMelhorado}
                  placeholder="Seu nome"
                  value={novoNome}
                  onChangeText={setNovoNome}
                  placeholderTextColor="#2196F3"
                  autoCapitalize="words"
                />
              </View>
              <View style={styles.inputBox}>
                <MaterialIcons name="calendar-today" size={20} color="#2196F3" style={{ marginRight: 6 }} />
                <TextInput
                  style={styles.inputMelhorado}
                  placeholder="Data (dd/mm/aaaa)"
                  value={novaData}
                  onChangeText={t => setNovaData(formatarDataInput(t))}
                  placeholderTextColor="#2196F3"
                  keyboardType="numeric"
                  maxLength={10}
                />
              </View>
              <View style={styles.funçõesFormBox}>
                <Text style={styles.funçõesFormTítulo}>Função no Ministério de Louvor</Text>
                <View style={styles.funçõesChipsContainer}>
                  {FUNCOES_PADRAO.map(função => {
                    const selecionada = funçõesSelecionadas.includes(função);
                    return (
                      <TouchableOpacity
                        key={função}
                        style={[styles.funçãoChipEditavel, selecionada && styles.funçãoChipSelecionada]}
                        onPress={() => alternarFuncao(função)}
                        activeOpacity={0.8}
                      >
                        <Text style={[styles.funçãoChipTexto, selecionada && styles.funçãoChipTextoSelecionado]}>
                          {função}
                        </Text>
                      </TouchableOpacity>
                    );
                  })}
                </View>
                <View style={styles.inputBox}>
                  <MaterialIcons name="add-circle-outline" size={20} color="#2196F3" style={{ marginRight: 6 }} />
                  <TextInput
                    style={styles.inputMelhorado}
                    placeholder="Outra função"
                    value={novaFuncao}
                    onChangeText={setNovaFuncao}
                    placeholderTextColor="#2196F3"
                    autoCapitalize="words"
                  />
                </View>
              </View>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 10 }}>
                <TouchableOpacity
                  style={[styles.botaoAddMelhorado, { flex: 1, backgroundColor: '#e53935' }]}
                  onPress={() => {
                    setMostrarForm(false);
                    setNovaFuncao('');
                    setFuncoesSelecionadas([]);
                  }}
                  activeOpacity={0.85}
                >
                  <MaterialIcons name="close" size={22} color="#fff" />
                  <Text style={styles.textoBotaoAdd}>Cancelar</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[styles.botaoAddMelhorado, { flex: 1 }]}
                  onPress={adicionarAniversariante}
                  activeOpacity={0.85}
                >
                  <MaterialIcons name="check-circle" size={22} color="#fff" />
                  <Text style={styles.textoBotaoAdd}>Salvar</Text>
                </TouchableOpacity>
              </View>
            </Neumorphic>
          )}

          <FlatList
            data={todosAniversariantes}
            keyExtractor={item => item.id || item.nome + item.data}
            contentContainerStyle={{ paddingBottom: 40 }}
            renderItem={({ item }) => (
                <LinearGradient
                  colors={['#FFB84D', '#43E97B', '#46D7FF']}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.cardWrapper}
                >
                {/* CARD PRINCIPAL */}
                <LinearGradient
                  colors={['#151C3C', '#222047', '#2D2146']}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.cardAll}
                >
                  <View style={styles.cardGlow} />
                  <TouchableOpacity
                    style={styles.avatarAllButton}
                    onPress={() => alterarFotoAniversariante(item.nome)}
                    activeOpacity={0.8}
                  >
                    <Image
                      source={{ uri: obterFotoAniversariante(item.nome) }}
                      style={styles.avatarAll}
                    />
                  </TouchableOpacity>
                  <View style={styles.cardAllContent}>
                    <Text style={styles.nomeAll} numberOfLines={2}>{item.nome}</Text>
                    <Text style={styles.dataAll}>{exibirDiaMes(item.data)}</Text>
                    {!!item.funções?.length && (
                      <View style={styles.funçõesCardContainer}>
                        {item.funções.map(função => (
                          <View key={função} style={styles.funçãoChipCard}>
                            <MaterialIcons name="music-note" size={12} color="#43e97b" />
                            <Text style={styles.funçãoChipCardTexto}>{função}</Text>
                          </View>
                        ))}
                      </View>
                    )}
                  </View>
                  <View style={styles.acoesDiscretasCard}>
                    <TouchableOpacity
                      style={styles.botaoAcaoDiscreta}
                      onPress={() => alterarFotoAniversariante(item.nome)}
                      activeOpacity={0.75}
                    >
                      <MaterialIcons name={podeEditarFoto(item.nome) ? 'photo-camera' : 'visibility'} size={13} color="#b8c7dd" />
                    </TouchableOpacity>
                    <TouchableOpacity
                      style={styles.botaoAcaoDiscreta}
                      onPress={() => abrirEdicaoFuncoes(item)}
                      activeOpacity={0.75}
                    >
                      <MaterialIcons name="edit" size={13} color="#b8c7dd" />
                    </TouchableOpacity>
                    {item.mensagens && item.mensagens.length > 0 && (
                      <TouchableOpacity
                        style={[styles.botaoAcaoDiscreta, styles.botaoMensagemDiscreto]}
                        onPress={() => {
                          setAniversarianteSelecionado(item);
                          setModalMensagensVisible(true);
                        }}
                        activeOpacity={0.75}
                      >
                        <MaterialIcons name="mail" size={13} color="#ffbc62" />
                        <Text style={styles.contadorMensagens}>{item.mensagens.length}</Text>
                      </TouchableOpacity>
                    )}
                  </View>
                </LinearGradient>
              </LinearGradient>
            )}
            ListEmptyComponent={
              <Text style={{ color: '#2196F3', textAlign: 'center', marginTop: 10 }}>
                Nenhum aniversariante cadastrado.
              </Text>
            }
          />

          {/* Modal de enviar mensagem */}
          <Modal
            visible={modalVisible}
            animationType="slide"
            transparent
            onRequestClose={() => setModalVisible(false)}
          >
            <View style={styles.modalBg}>
              <Neumorphic style={styles.modalBox}>
                <Text style={styles.modalTítulo}>
                  Enviar mensagem para {aniversarianteSelecionado?.nome}
                </Text>
                <TextInput
                  style={styles.inputModal}
                  placeholder="Digite sua mensagem"
                  value={mensagem}
                  onChangeText={setMensagem}
                  placeholderTextColor="#2196F3"
                  multiline
                />
                <View style={{ flexDirection: 'row', justifyContent: 'flex-end', gap: 12 }}>
                  <TouchableOpacity onPress={() => setModalVisible(false)}>
                    <Text style={{ color: '#e53935', fontWeight: 'bold', fontSize: 16 }}>Cancelar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity onPress={enviarMensagem}>
                    <Text style={{ color: '#2196F3', fontWeight: 'bold', fontSize: 16 }}>Enviar</Text>
                  </TouchableOpacity>
                </View>
              </Neumorphic>
            </View>
          </Modal>

          {/* Modal de visualizar mensagens */}
          <Modal
            visible={modalMensagensVisible}
            animationType="slide"
            transparent
            onRequestClose={() => setModalMensagensVisible(false)}
          >
            <View style={styles.modalBg}>
              <Neumorphic style={styles.modalMensagensBox}>
                <Text style={styles.modalTítulo}>
                  Mensagens para {aniversarianteSelecionado?.nome} 🎉
                </Text>
                <ScrollView style={styles.mensagensContainer}>
                  {aniversarianteSelecionado?.mensagens?.map((msg, index) => {
                    const mensagemObj = typeof msg === 'string' ? { texto: msg } : msg;
                    const dataHoraMensagem = formatarDataHoraMensagem(mensagemObj.enviadoEm);
                    return (
                      <View key={index} style={styles.mensagemItem}>
                        <Text style={styles.mensagemTexto}>"{mensagemObj.texto}"</Text>
                        {!!dataHoraMensagem && (
                          <Text style={styles.mensagemDataHora}>
                            Recebida em {dataHoraMensagem}
                          </Text>
                        )}
                        <View style={{ flexDirection: 'row', marginTop: 6, alignItems: 'center' }}>
                          {mensagemObj.reacao ? (
                            <Text style={{ fontSize: 22 }}>{normalizarReacaoMensagem(mensagemObj.reacao)}</Text>
                          ) : (
                            <>
                              <TouchableOpacity
                                style={{ marginRight: 10 }}
                                onPress={() => responderMensagem(index, '❤️')}
                              >
                                <Text style={{ fontSize: 22 }}>❤️</Text>
                              </TouchableOpacity>
                              <TouchableOpacity
                                style={{ marginRight: 10 }}
                                onPress={() => responderMensagem(index, '🙏')}
                              >
                                <Text style={{ fontSize: 22 }}>🙏</Text>
                              </TouchableOpacity>
                              <TouchableOpacity
                                onPress={() => responderMensagem(index, '👍')}
                              >
                                <Text style={{ fontSize: 22 }}>👍</Text>
                              </TouchableOpacity>
                            </>
                          )}
                        </View>
                      </View>
                    );
                  })}
                </ScrollView>
                <TouchableOpacity 
                  style={styles.botaoFecharModal}
                  onPress={() => setModalMensagensVisible(false)}
                >
                  <Text style={styles.textoFecharModal}>Fechar</Text>
                </TouchableOpacity>
              </Neumorphic>
            </View>
          </Modal>

          <Modal
            visible={!!fotoVisualizada}
            animationType="fade"
            transparent
            onRequestClose={() => setFotoVisualizada(null)}
          >
            <View style={styles.modalBg}>
              <Neumorphic style={styles.modalFotoBox}>
                <Text style={styles.modalTítulo}>{fotoVisualizada?.nome}</Text>
                {fotoVisualizada?.uri ? (
                  <Image source={{ uri: fotoVisualizada.uri }} style={styles.fotoVisualizada} />
                ) : null}
                <TouchableOpacity
                  style={styles.botaoFecharModal}
                  onPress={() => setFotoVisualizada(null)}
                >
                  <Text style={styles.textoFecharModal}>Fechar</Text>
                </TouchableOpacity>
              </Neumorphic>
            </View>
          </Modal>

          {/* Modal de editar funções */}
          <Modal
            visible={modalFuncoesVisible}
            animationType="slide"
            transparent
            onRequestClose={() => setModalFuncoesVisible(false)}
          >
            <View style={styles.modalBg}>
              <Neumorphic style={styles.modalBox}>
                <Text style={styles.modalTítulo}>
                  Dados de {aniversarianteSelecionado?.nome}
                </Text>
                <TouchableOpacity
                  style={styles.botaoFotoModal}
                  onPress={() => aniversarianteSelecionado && alterarFotoAniversariante(aniversarianteSelecionado.nome)}
                  activeOpacity={0.85}
                >
                  <MaterialIcons name={aniversarianteSelecionado && podeEditarFoto(aniversarianteSelecionado.nome) ? 'photo-camera' : 'visibility'} size={20} color="#fff" />
                  <Text style={styles.textoBotaoFotoModal}>
                    {aniversarianteSelecionado && podeEditarFoto(aniversarianteSelecionado.nome) ? 'Editar foto' : 'Ver foto'}
                  </Text>
                </TouchableOpacity>
                <View style={styles.inputBox}>
                  <MaterialIcons name="person" size={20} color="#2196F3" style={{ marginRight: 6 }} />
                  <TextInput
                    style={styles.inputMelhorado}
                    placeholder="Nome"
                    value={nomeEditado}
                    onChangeText={setNomeEditado}
                    placeholderTextColor="#2196F3"
                    autoCapitalize="words"
                  />
                </View>
                <View style={styles.inputBox}>
                  <MaterialIcons name="calendar-today" size={19} color="#2196F3" style={{ marginRight: 6 }} />
                  <TextInput
                    style={styles.inputMelhorado}
                    placeholder="Data (dd/mm/aaaa)"
                    value={dataEditada}
                    onChangeText={t => setDataEditada(formatarDataInput(t))}
                    placeholderTextColor="#2196F3"
                    keyboardType="numeric"
                    maxLength={10}
                  />
                </View>
                <Text style={styles.funçõesFormTítulo}>Função no Ministério de Louvor</Text>
                {funçõesSelecionadas.length > 0 && (
                  <View style={styles.funçõesEditaveisLista}>
                    {funçõesSelecionadas.map((função, index) => (
                      <View key={`${função}-${index}`} style={styles.funçãoEditavelLinha}>
                        <MaterialIcons name="music-note" size={17} color="#43e97b" style={{ marginRight: 6 }} />
                        <TextInput
                          style={styles.inputFuncaoEditavel}
                          value={função}
                          onChangeText={valor => editarFuncaoSelecionada(index, valor)}
                          placeholder="Funcao"
                          placeholderTextColor="#6aa8d9"
                          autoCapitalize="words"
                        />
                        <TouchableOpacity
                          style={styles.botaoExcluirFuncao}
                          onPress={() => excluirFuncaoSelecionada(index)}
                          activeOpacity={0.75}
                        >
                          <MaterialIcons name="close" size={16} color="#ffb3b3" />
                        </TouchableOpacity>
                      </View>
                    ))}
                  </View>
                )}
                <Text style={styles.funçõesAtalhoTítulo}>Adicionar função padrao</Text>
                <View style={styles.funçõesChipsContainer}>
                  {FUNCOES_PADRAO.map(função => {
                    const selecionada = funçõesSelecionadas.includes(função);
                    return (
                      <TouchableOpacity
                        key={função}
                        style={[styles.funçãoChipEditavel, selecionada && styles.funçãoChipSelecionada]}
                        onPress={() => alternarFuncao(função)}
                        activeOpacity={0.8}
                      >
                        <Text style={[styles.funçãoChipTexto, selecionada && styles.funçãoChipTextoSelecionado]}>
                          {função}
                        </Text>
                      </TouchableOpacity>
                    );
                  })}
                </View>
                <View style={styles.inputBox}>
                  <MaterialIcons name="add-circle-outline" size={20} color="#2196F3" style={{ marginRight: 6 }} />
                  <TextInput
                    style={styles.inputMelhorado}
                    placeholder="Adicionar outra função"
                    value={novaFuncao}
                    onChangeText={setNovaFuncao}
                    placeholderTextColor="#2196F3"
                    autoCapitalize="words"
                  />
                </View>
                <View style={{ flexDirection: 'row', justifyContent: 'flex-end', gap: 12, marginTop: 14 }}>
                  <TouchableOpacity onPress={() => setModalFuncoesVisible(false)}>
                    <Text style={{ color: '#e53935', fontWeight: 'bold', fontSize: 16 }}>Cancelar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity onPress={salvarFuncoesAniversariante}>
                    <Text style={{ color: '#2196F3', fontWeight: 'bold', fontSize: 16 }}>Salvar</Text>
                  </TouchableOpacity>
                </View>
              </Neumorphic>
            </View>
          </Modal>
        </View>
      </ScrollView>
    </LinearGradient>
  );
}

