function getHojeDate() {
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);
  return hoje;
}

function dateParaData(dataSelecionada: Date) {
  const dia = String(dataSelecionada.getDate()).padStart(2, '0');
  const mes = String(dataSelecionada.getMonth() + 1).padStart(2, '0');
  const ano = dataSelecionada.getFullYear();
  return `${dia}/${mes}/${ano}`;
}

function dataParaDate(dataTexto?: string) {
  if (!dataTexto || dataTexto.length < 10) return getHojeDate();
  const [dia, mes, ano] = dataTexto.split(/[/-]/).map(Number);
  if (!dia || !mes || !ano) return getHojeDate();
  return new Date(ano, mes - 1, dia);
}

const MESES = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro',
];

const DIAS_SEMANA = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];

const NOTAS = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const ENARMONICOS: Record<string, string> = {
  Db: 'C#',
  Eb: 'D#',
  Gb: 'F#',
  Ab: 'G#',
  Bb: 'A#',
};
const ACORDE_REGEX = /(^|[\s[(|])([A-G](?:#|b)?)(m?)([^/\s\])|]*)(?:\/([A-G](?:#|b)?))?/g;
const ACORDE_TOKEN_REGEX = /^[A-G](?:#|b)?m?(?:maj7|maj9|m7|m9|m11|m13|7M|7|9|11|13|6|4|2|sus2|sus4|sus|dim|aug|add9|º|°)?(?:\/[A-G](?:#|b)?)?$/;
const ACORDE_COLCHETES_REGEX = /\[([A-G](?:#|b)?m?[^/\]\s]*(?:\/[A-G](?:#|b)?)?)\]/g;

function normalizarNota(nota: string) {
  return ENARMONICOS[nota] || nota;
}

function transporNota(nota: string, semitons: number) {
  const normalizada = normalizarNota(nota);
  const index = NOTAS.indexOf(normalizada);
  if (index < 0) return nota;
  return NOTAS[(index + semitons + NOTAS.length) % NOTAS.length];
}

function obterNotaBase(tom?: string) {
  if (!tom) return '';
  const match = tom.trim().match(/^([A-G](?:#|b)?)/);
  return match ? normalizarNota(match[1]) : '';
}

function obterSemitons(origem?: string, destino?: string) {
  const notaOrigem = obterNotaBase(origem);
  const notaDestino = obterNotaBase(destino);
  const origemIndex = NOTAS.indexOf(notaOrigem);
  const destinoIndex = NOTAS.indexOf(notaDestino);
  if (origemIndex < 0 || destinoIndex < 0) return 0;
  return destinoIndex - origemIndex;
}

function extrairTextoCifra(cifra: CifraJson) {
  if (typeof cifra.letra === 'string') return cifra.letra;
  if (Array.isArray(cifra.linhas)) {
    return cifra.linhas
      .map(linha => {
        if (typeof linha === 'string') return linha;
        return [linha.cifra, linha.texto].filter(Boolean).join('\n');
      })
      .join('\n');
  }
  return '';
}

function transporCifraTexto(texto: string, tomOrigem: string, tomDestino: string) {
  const semitons = obterSemitons(tomOrigem, tomDestino);
  if (!semitons) return texto;

  const transporTrecho = (trecho: string) => trecho.replace(ACORDE_REGEX, (match, prefixo, nota, menor, sufixo = '', baixo) => {
    const notaTransposta = transporNota(nota, semitons);
    const baixoTransposto = baixo ? `/${transporNota(baixo, semitons)}` : '';
    return `${prefixo}${notaTransposta}${menor}${sufixo}${baixoTransposto}`;
  });

  return texto
    .split('\n')
    .map(linha => {
      const linhaComColchetes = linha.replace(ACORDE_COLCHETES_REGEX, (_match, acorde) => `[${transporTrecho(acorde)}]`);
      const tokens = linhaComColchetes.trim().split(/\s+/).filter(Boolean);
      if (!tokens.length) return linhaComColchetes;

      const acordes = tokens.filter(token => ACORDE_TOKEN_REGEX.test(token.replace(/[|()[\]]/g, '')));
      const pareceLinhaDeCifra = acordes.length > 0 && acordes.length / tokens.length >= 0.6;
      return pareceLinhaDeCifra ? transporTrecho(linhaComColchetes) : linhaComColchetes;
    })
    .join('\n');
}

function parseCifraJson(valor: string): CifraJson | null {
  if (!valor.trim()) return null;
  const parsed = JSON.parse(valor);
  if (!parsed || typeof parsed !== 'object') {
    throw new Error('JSON inválido');
  }
  return parsed as CifraJson;
}

function normalizarNome(nome: string) {
  return nome
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\b(pr|pra|pastor|pastora|apa|ap)\b\.?/g, '')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

function obterFotoPorNome(fotosUsuarios: Record<string, string>, nome: string) {
  if (fotosUsuarios[nome]) return fotosUsuarios[nome];

  const nomeNormalizado = normalizarNome(nome);
  const chaveFoto = Object.keys(fotosUsuarios).find(chave => {
    const chaveNormalizada = normalizarNome(chave);
    return (
      chaveNormalizada === nomeNormalizado ||
      nomeNormalizado.includes(chaveNormalizada) ||
      chaveNormalizada.includes(nomeNormalizado)
    );
  });

  return chaveFoto ? fotosUsuarios[chaveFoto] : undefined;
}

function montarDiasCalendario(mesVisivel: Date) {
  const ano = mesVisivel.getFullYear();
  const mes = mesVisivel.getMonth();
  const primeiroDia = new Date(ano, mes, 1).getDay();
  const totalDias = new Date(ano, mes + 1, 0).getDate();
  const dias: Array<Date | null> = Array(primeiroDia).fill(null);

  for (let dia = 1; dia <= totalDias; dia += 1) {
    dias.push(new Date(ano, mes, dia));
  }

  while (dias.length % 7 !== 0) dias.push(null);
  return dias;
}

